import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for batched matrix multiplication
batched_matmul_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void batched_gemm_kernel(const float* A, const float* B, float* C, 
                                    int N, int M, int K, int L) {
    const int n = blockIdx.z;
    const int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    const int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    __shared__ float Ashared[TILE_SIZE][TILE_SIZE];
    __shared__ float Bshared[TILE_SIZE][TILE_SIZE];

    float acc = 0.0;

    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        const int tiled_k = t * TILE_SIZE;
        const int A_col = tiled_k + threadIdx.x;
        const int B_row = tiled_k + threadIdx.y;

        if (row < M && A_col < K)
            Ashared[threadIdx.y][threadIdx.x] = A[n*M*K + row*K + A_col];
        else
            Ashared[threadIdx.y][threadIdx.x] = 0.0;

        if (B_row < K && col < L)
            Bshared[threadIdx.y][threadIdx.x] = B[B_row*L + col];
        else
            Bshared[threadIdx.y][threadIdx.x] = 0.0;

        __syncthreads();

        for (int k = 0; k < TILE_SIZE; ++k) {
            acc += Ashared[threadIdx.y][k] * Bshared[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < M && col < L)
        C[n*M*L + row*L + col] = acc;
}

torch::Tensor batched_gemm_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 3, "A must be 3D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be 2D matrix");

    const int N = A.size(0);
    const int M = A.size(1);
    const int K = A.size(2);
    const int L = B.size(1);

    auto C = torch::zeros({N, M, L}, A.options());

    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((L + TILE_SIZE-1)/TILE_SIZE, 
              (M + TILE_SIZE-1)/TILE_SIZE, 
              N);

    batched_gemm_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N, M, K, L
    );

    return C;
}
"""

batched_matmul_cpp = "torch::Tensor batched_gemm_cuda(torch::Tensor A, torch::Tensor B);"

# Load the custom kernel
batched_gemm = load_inline(
    name="batched_gemm",
    cpp_sources=batched_matmul_cpp,
    cuda_sources=batched_matmul_source,
    functions=["batched_gemm_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.custom_gemm = batched_gemm

    def forward(self, A, B):
        return self.custom_gemm.batched_gemm_cuda(A, B)
